6	const MAX_ACTIONABLE_STDERR_LINES = 32;
7	const ACTIONABLE_STDERR_HEAD_LINES = 8;
8	const ACTIONABLE_STDERR_TAIL_LINES = MAX_ACTIONABLE_STDERR_LINES - ACTIONABLE_STDERR_HEAD_LINES;
9	const MAX_ACTIONABLE_STDERR_BYTES = 16 * 1024;
10	const MAX_ACTIONABLE_STDERR_LINE_BYTES = Math.floor(
11	  (MAX_ACTIONABLE_STDERR_BYTES - (MAX_ACTIONABLE_STDERR_LINES - 1)) /
12	    MAX_ACTIONABLE_STDERR_LINES,
13	);
14	const TRUNCATION_MARKER = '…';
15	
16	export interface RunToolOptions {
17	  readonly cwd?: string;
18	  readonly env?: Record<string, string>;
19	  readonly errorFile?: string;
20	  readonly timeoutSeconds?: number;
21	}
22	
23	export interface RunToolResult {
24	  readonly success: boolean;
25	  readonly message: string;
26	  readonly exitCode: number;
27	  readonly actionableStderr: readonly string[];
28	}
29	
30	/** Run one Deno task at the emitted runtime edge. */
31	export async function runTool(
32	  taskName: string,
33	  options: RunToolOptions = {},
34	): Promise<RunToolResult> {
35	  if (options.errorFile) {
36	    await Deno.remove(options.errorFile).catch((error) => {
37	      if (!(error instanceof Deno.errors.NotFound)) throw error;
38	    });
39	  }
40	
41	  const child = new Deno.Command('deno', {
42	    args: ['task', taskName],
43	    cwd: options.cwd,
44	    env: options.env,
45	    stdin: 'inherit',
46	    stdout: 'piped',
47	    stderr: 'piped',
48	  }).spawn();
49	
50	  const actionableStderrHead: string[] = [];
51	  const actionableStderrTail: string[] = [];
52	  let stderrBuffer = '';
53	  let timedOut = false;
54	  const decoder = new TextDecoder();
55	  function captureActionableLines(flush = false): void {
56	    const lines = stderrBuffer.split(/\r?\n/);
57	    stderrBuffer = flush ? '' : lines.pop() ?? '';
58	    for (const line of lines) {
59	      const detail = stripVTControlCharacters(line).trim();
60	      if (!detail || detail.startsWith('Task ')) continue;
61	      const boundedDetail = truncateUtf8(detail, MAX_ACTIONABLE_STDERR_LINE_BYTES);
62	      if (actionableStderrHead.length < ACTIONABLE_STDERR_HEAD_LINES) {
63	        actionableStderrHead.push(boundedDetail);
64	        continue;
65	      }
66	      if (actionableStderrTail.length === ACTIONABLE_STDERR_TAIL_LINES) {
67	        actionableStderrTail.shift();
68	      }
69	      actionableStderrTail.push(boundedDetail);
70	    }
71	  }
72	  const captureStderr = (async () => {
73	    for await (const chunk of child.stderr) {
74	      await Deno.stderr.write(chunk);
75	      stderrBuffer += decoder.decode(chunk, { stream: true });
76	      captureActionableLines();
77	    }
78	    stderrBuffer += decoder.decode();
79	    stderrBuffer += '\n';
80	    captureActionableLines(true);
81	  })();
82	
83	  const timeoutId = options.timeoutSeconds === undefined ? undefined : setTimeout(() => {
84	    try {
85	      child.kill('SIGTERM');
86	      timedOut = true;
87	    } catch {
88	      // The process won the race with the timeout callback.
89	    }
90	  }, options.timeoutSeconds * 1_000);
91	  const stdout = child.stdout.pipeTo(Deno.stdout.writable, { preventClose: true });
92	  const status = await child.status;
93	  if (timeoutId !== undefined) clearTimeout(timeoutId);
94	  await Promise.all([stdout, captureStderr]);
95	
96	  const actionableStderr = [...actionableStderrHead, ...actionableStderrTail];
97	  const success = status.success && !timedOut;
98	  const message = timedOut
99	    ? `deno task ${taskName} timed out after ${options.timeoutSeconds} seconds`
100	    : success
101	    ? `deno task ${taskName} completed successfully`
102	    : actionableStderr[0] || `deno task ${taskName} exited with code ${status.code}`;
103	  if (!success && options.errorFile) {
104	    await Deno.writeTextFile(
105	      options.errorFile,
106	      timedOut || actionableStderr.length === 0 ? message : actionableStderr.join('\n'),
107	    );
108	  }
109	
110	  return { success, message, exitCode: status.code, actionableStderr };
111	}
112	
113	function truncateUtf8(text: string, maxBytes: number): string {
114	  const encoder = new TextEncoder();
115	  const encoded = encoder.encode(text);
116	  if (encoded.byteLength <= maxBytes) return text;
