118	  const markerBytes = encoder.encode(TRUNCATION_MARKER).byteLength;
119	  const contentBytes = maxBytes - markerBytes;
120	  const headBytes = Math.floor(contentBytes / 3);
121	  const tailBytes = contentBytes - headBytes;
122	  let headEnd = headBytes;
123	  while (headEnd > 0 && (encoded[headEnd] & 0b1100_0000) === 0b1000_0000) headEnd--;
124	  let tailStart = encoded.byteLength - tailBytes;
125	  while (
126	    tailStart < encoded.byteLength &&
127	    (encoded[tailStart] & 0b1100_0000) === 0b1000_0000
128	  ) tailStart++;
129	  const decoder = new TextDecoder();
130	  return `${decoder.decode(encoded.subarray(0, headEnd))}${TRUNCATION_MARKER}${
131	    decoder.decode(encoded.subarray(tailStart))
132	  }`;
133	}
