// run-tool.mts — GENERATED BY @netscript/cli. DO NOT EDIT.
// Runs an Aspire tool while retaining bounded actionable stderr for command state reporting.

import { stripVTControlCharacters } from 'node:util';

const MAX_ACTIONABLE_STDERR_LINES = 32;
const ACTIONABLE_STDERR_HEAD_LINES = 8;
const ACTIONABLE_STDERR_TAIL_LINES = MAX_ACTIONABLE_STDERR_LINES - ACTIONABLE_STDERR_HEAD_LINES;
const MAX_ACTIONABLE_STDERR_BYTES = 16 * 1024;
const MAX_ACTIONABLE_STDERR_LINE_BYTES = Math.floor(
  (MAX_ACTIONABLE_STDERR_BYTES - (MAX_ACTIONABLE_STDERR_LINES - 1)) /
    MAX_ACTIONABLE_STDERR_LINES,
);
const TRUNCATION_MARKER = '…';

export interface RunToolOptions {
  readonly cwd?: string;
  readonly env?: Record<string, string>;
  readonly errorFile?: string;
  readonly timeoutSeconds?: number;
}

export interface RunToolResult {
  readonly success: boolean;
  readonly message: string;
  readonly exitCode: number;
  readonly actionableStderr: readonly string[];
}

/** Run one Deno task at the emitted runtime edge. */
export async function runTool(
  taskName: string,
  options: RunToolOptions = {},
): Promise<RunToolResult> {
  if (options.errorFile) {
    await Deno.remove(options.errorFile).catch((error) => {
      if (!(error instanceof Deno.errors.NotFound)) throw error;
    });
  }

  const child = new Deno.Command('deno', {
    args: ['task', taskName],
    cwd: options.cwd,
    env: options.env,
    stdin: 'inherit',
    stdout: 'piped',
    stderr: 'piped',
  }).spawn();

  const actionableStderrHead: string[] = [];
  const actionableStderrTail: string[] = [];
  let stderrBuffer = '';
  let timedOut = false;
  const decoder = new TextDecoder();
  function captureActionableLines(flush = false): void {
    const lines = stderrBuffer.split(/\r?\n/);
    stderrBuffer = flush ? '' : lines.pop() ?? '';
    for (const line of lines) {
      const detail = stripVTControlCharacters(line).trim();
      if (!detail || detail.startsWith('Task ')) continue;
      const boundedDetail = truncateUtf8(detail, MAX_ACTIONABLE_STDERR_LINE_BYTES);
      if (actionableStderrHead.length < ACTIONABLE_STDERR_HEAD_LINES) {
        actionableStderrHead.push(boundedDetail);
        continue;
      }
      if (actionableStderrTail.length === ACTIONABLE_STDERR_TAIL_LINES) {
        actionableStderrTail.shift();
      }
      actionableStderrTail.push(boundedDetail);
    }
  }
  const captureStderr = (async () => {
    for await (const chunk of child.stderr) {
      await Deno.stderr.write(chunk);
      stderrBuffer += decoder.decode(chunk, { stream: true });
      captureActionableLines();
    }
    stderrBuffer += decoder.decode();
    stderrBuffer += '\n';
    captureActionableLines(true);
  })();

  const timeoutId = options.timeoutSeconds === undefined ? undefined : setTimeout(() => {
    try {
      child.kill('SIGTERM');
      timedOut = true;
    } catch {
      // The process won the race with the timeout callback.
    }
  }, options.timeoutSeconds * 1_000);
  const stdout = child.stdout.pipeTo(Deno.stdout.writable, { preventClose: true });
  const status = await child.status;
  if (timeoutId !== undefined) clearTimeout(timeoutId);
  await Promise.all([stdout, captureStderr]);

  const actionableStderr = [...actionableStderrHead, ...actionableStderrTail];
  const success = status.success && !timedOut;
  const message = timedOut
    ? `deno task ${taskName} timed out after ${options.timeoutSeconds} seconds`
    : success
    ? `deno task ${taskName} completed successfully`
    : actionableStderr[0] || `deno task ${taskName} exited with code ${status.code}`;
  if (!success && options.errorFile) {
    await Deno.writeTextFile(
      options.errorFile,
      timedOut || actionableStderr.length === 0 ? message : actionableStderr.join('\n'),
    );
  }

  return { success, message, exitCode: status.code, actionableStderr };
}

function truncateUtf8(text: string, maxBytes: number): string {
  const encoder = new TextEncoder();
  const encoded = encoder.encode(text);
  if (encoded.byteLength <= maxBytes) return text;

  const markerBytes = encoder.encode(TRUNCATION_MARKER).byteLength;
  const contentBytes = maxBytes - markerBytes;
  const headBytes = Math.floor(contentBytes / 3);
  const tailBytes = contentBytes - headBytes;
  let headEnd = headBytes;
  while (headEnd > 0 && (encoded[headEnd] & 0b1100_0000) === 0b1000_0000) headEnd--;
  let tailStart = encoded.byteLength - tailBytes;
  while (
    tailStart < encoded.byteLength &&
    (encoded[tailStart] & 0b1100_0000) === 0b1000_0000
  ) tailStart++;
  const decoder = new TextDecoder();
  return `${decoder.decode(encoded.subarray(0, headEnd))}${TRUNCATION_MARKER}${
    decoder.decode(encoded.subarray(tailStart))
  }`;
}

if (import.meta.main) {
  if (Deno.args[0] === '--request') {
    const [, requestPath, taskSuffix] = Deno.args;
    if (!requestPath || !taskSuffix) {
      console.error('Tool runner request mode requires a request file and task suffix.');
      Deno.exit(2);
    }
    const request = parseOperationRequest(await Deno.readTextFile(requestPath));
    const operation = request.NETSCRIPT_PRISMA_OPERATION;
    if (!operation || !/^[a-z-]+$/.test(operation)) {
      console.error('Invalid NetScript database operation request.');
      Deno.exit(2);
    }
    const configuredTimeout = request.ASPIRE_CLI_START_TIMEOUT;
    const timeoutSeconds = configuredTimeout ? Number(configuredTimeout) : undefined;
    if (timeoutSeconds !== undefined && (!Number.isInteger(timeoutSeconds) || timeoutSeconds < 1)) {
      console.error('Tool runner request timeout must be a positive whole number.');
      Deno.exit(2);
    }
    const result = await runTool(`db:${operation}:${taskSuffix}`, {
      env: request,
      timeoutSeconds,
    });
    Deno.exit(result.exitCode);
  }

  const [errorFile, taskName, timeoutValue] = Deno.args;
  if (!errorFile || !taskName) {
    console.error('Tool runner requires an error file and task name.');
    Deno.exit(2);
  }

  const timeoutSeconds = timeoutValue ? Number(timeoutValue) : undefined;
  if (timeoutSeconds !== undefined && (!Number.isInteger(timeoutSeconds) || timeoutSeconds < 1)) {
    console.error('Tool runner timeout must be a positive whole number.');
    Deno.exit(2);
  }

  const result = await runTool(taskName, { errorFile, timeoutSeconds });
  Deno.exit(result.exitCode);
}

function parseOperationRequest(text: string): Record<string, string> {
  const parsed: unknown = JSON.parse(text);
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error('Database operation request must be an object.');
  }
  const request: Record<string, string> = {};
  for (const [key, value] of Object.entries(parsed)) {
    if (typeof value !== 'string') {
      throw new Error(`Database operation request value ${key} must be a string.`);
    }
    request[key] = value;
  }
  return request;
}

